TYPE_LABELS = {
    "Org": "Organization",
    "Person": "Person",
    "Personal": "Person",
    "Award": "Award",
    "Awards": "Award",
    "Prize": "Award",
    "Grant": "Award",
    "Winner": "Winner",
    "Fellow": "Person",
    "Place": "Location",
    "Location": "Location",
    "Work": "Work",
    "Journal": "Journal",
    "Library": "Library",
    "Archive": "Archive",
}

def _type_name(type_id):
    if type_id in TYPE_NAME_OVERRIDES:
        return TYPE_NAME_OVERRIDES[type_id]

    parts = type_id.split("_")
    label = next((TYPE_LABELS[p] for p in reversed(parts) if p in TYPE_LABELS), "Entity")
    display = " ".join(parts).replace(" Id", " ID").replace(" 2", "")
    return f"{label} -- {display}"


manifest = {
    "versions": ["0.2"],
    "defaultTypes": [{"id": type_id, "name": _type_name(type_id)} for type_id in DEFAULT_TYPE_IDS],
    "identifierSpace": "/doc/#identifierSpace",
    "schemaSpace": "/doc/#schemaSpace",
    "name": "BookReconciler Service",
    "batchSize": 1,
    "preview": {
        "height": 200,
        "url": use_endpoint_address + "/api/v1/preview?id={{id}}",
        "width": 500,
    },
    "view": {
        "url": use_endpoint_address + "/api/v1/redirect?id={{id}}",
    },
    "suggest": {
        "property": {
            "service_url": use_endpoint_address + "/api/v1/reconcile",
            "service_path": "/suggest/property",
        },
    },
    "extend": {
        "propose_properties": {
            "service_url": use_endpoint_address + "/api/v1/reconcile",
            "service_path": "/extend_suggest",
        },
    },
}
